insert into public.productos (id, slug, nombre, marca, modelo, categoria_id, descripcion, caracteristicas, incluye, garantia, faq, estado, orden, meta_titulo, meta_descripcion, created_at, updated_at, clave)
select r.id, r.slug, r.nombre, r.marca, r.modelo, (select c.id from public.categorias c join _cat m on m.slug = c.slug where m.local_id = r.categoria_id), r.descripcion, r.caracteristicas, r.incluye, r.garantia, r.faq, r.estado, r.orden, r.meta_titulo, r.meta_descripcion, r.created_at, r.updated_at, r.clave
